            raise
        finally:
            stop_event.set()
            thread.join()
            state.update(heartbeat_at=time.time(), finished_at=time.time())
            save(ROOT / "runner.json", state)
            save(ROOT / "progress.json", state)
            save(ROOT / "outcomes.json", {a: {p["pair_id"]: {
